-- Lot T7 des Tarides (03/11/2026) : économie des Tarides. Généré par outils\economie_tarides.py : ne pas
-- modifier à la main. Le client lit les mêmes sorts dans patch-frFR-4.MPQ (auras_nommees.py --client).
SET SESSION sql_mode = '';
USE acore_world;

-- Camp : potion 3-4 et feu 4-5 (genre 1 potion, 2 feu ; objet 0 = or, en cuivre).
DELETE FROM solazeroth_v3_camp_couts WHERE (genre = 1 AND rang IN (3, 4)) OR (genre = 2 AND rang IN (4, 5));
DROP TABLE IF EXISTS solazeroth_v3_camp_rangs;
CREATE TABLE solazeroth_v3_camp_rangs (genre TINYINT UNSIGNED NOT NULL, rang TINYINT UNSIGNED NOT NULL, zone INT UNSIGNED NOT NULL, nom VARCHAR(80) NOT NULL, message VARCHAR(255) NOT NULL, PRIMARY KEY (genre, rang));

