-- Barème des annexes par point de part (haut : puissance la plus haute de la tranche).
DROP TABLE IF EXISTS solazeroth_v3_annexes_bareme;
CREATE TABLE solazeroth_v3_annexes_bareme (zone INT UNSIGNED NOT NULL, haut TINYINT UNSIGNED NOT NULL, cuivre INT UNSIGNED NOT NULL, eclats INT UNSIGNED NOT NULL, marques INT UNSIGNED NOT NULL, PRIMARY KEY (zone, haut));

-- Composants de donjon : puissance minimale des pièces de la zone du donjon (transfert de rang).
ALTER TABLE solazeroth_v3_donjons_composants ADD COLUMN puissance_min TINYINT UNSIGNED NOT NULL DEFAULT 1;
UPDATE solazeroth_v3_donjons_composants SET puissance_min = 1 WHERE carte = 389;

-- Dernier donjon terminé (son dernier boss), au compte : composant de la récompense de la semaine.
CREATE TABLE IF NOT EXISTS acore_characters.solazeroth_v3_dernier_donjon (compte INT UNSIGNED NOT NULL PRIMARY KEY, carte INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
